grid = FileAttachment("data/degeneracy-grid.json").json()

dx = grid.distances[1] - grid.distances[0]
dy = grid.inclinations[1] - grid.inclinations[0]

surface = grid.inclinations.flatMap((inc, i) =&gt;
  grid.distances.map((dist, j) =&gt; ({
    distance: dist,
    inclination: inc,
    difference: grid.difference[i][j],
    x1: dist - dx / 2,
    x2: dist + dx / 2,
    y1: inc - dy / 2,
    y2: inc + dy / 2
  }))
)

Plot.plot({
  height: 480,
  marginLeft: 70,
  marginBottom: 60,
  marginRight: 30,

  style: {
    fontSize: "14px",
    background: "transparent"
  },

  x: {
    label: "Luminosity distance (Mpc)"
  },

  y: {
    label: "Inclination (rad)"
  },

  color: {
    type: "sqrt",
    scheme: "viridis",
    reverse: true,
    label: "Relative waveform difference",
    legend: true,
    style: {
      background: "transparent"
    }
  },

  marks: [
    Plot.rect(surface, {
      x1: "x1",
      x2: "x2",
      y1: "y1",
      y2: "y2",
      fill: "difference"
    }),

    Plot.dot(
      [{
        distance: grid.reference.distance,
        inclination: grid.reference.inclination
      }],
      {
        x: "distance",
        y: "inclination",
        r: 7,
        symbol: "cross",
        stroke: "red",
        strokeWidth: 3
      }
    )
  ]
})

