waveforms = FileAttachment("data/waveform-bank.json").json()

reference = waveforms.find(d =&gt; d.label === "Reference")

viewof selectedLabel = Inputs.select(
  waveforms
    .filter(d =&gt; d.label !== "Reference")
    .map(d =&gt; d.label),
  {
    label: "Compare the reference with",
    value: "Valley A"
  }
)

selected = waveforms.find(d =&gt; d.label === selectedLabel)

waveformData = [
  ...reference.time.map((t, i) =&gt; ({
    time: t / 3600,
    strain: reference.strain[i] / 1e-17,
    source: "Reference"
  })),
  ...selected.time.map((t, i) =&gt; ({
    time: t / 3600,
    strain: selected.strain[i] / 1e-17,
    source: selected.label
  }))
]

Plot.plot({
  height: 400,
  marginLeft: 75,
  marginBottom: 60,

  style: {
    fontSize: "14px",
    background: "transparent"
  },

  x: {
    label: "Time since start of displayed segment (hours)"
  },

  y: {
    label: "Strain h₊ (×10⁻¹⁷)",
    grid: true
  },

  color: {
    domain: ["Reference", selected.label],
    range: ["#4c9be8", "#f28e2b"],
    legend: true
  },

  marks: [
    Plot.line(
      waveformData.filter(d =&gt; d.source === "Reference"),
      {
        x: "time",
        y: "strain",
        stroke: "#4c9be8",
        strokeWidth: 2.5
      }
    ),

    Plot.line(
      waveformData.filter(d =&gt; d.source !== "Reference"),
      {
        x: "time",
        y: "strain",
        stroke: "#f28e2b",
        strokeWidth: 1.8,
        strokeDasharray: "6,4"
      }
    )
  ]
})














































